			b.Materials[0].ActualGrams != "0" || b.Materials[0].DifferenceGrams != "-"+want.required {
			t.Fatalf("批次 %q 应投量应按绑定版本计算，得到 %+v", want.batchNo, b.Materials)
		}
	}
}

// 登记配方时物料编号重复仍按非法输入处理（ErrInvalidInput），
